((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 1) AND position = 1), 'wake up', '/weɪk ʌp/', 'thức dậy', 'PHRASE', 'I wake up before sunrise.', 'Tôi thức dậy trước khi mặt trời mọc.', 'BEGINNER', 'Daily Routine'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 1) AND position = 1), 'get dressed', '/ɡet drest/', 'mặc quần áo', 'PHRASE', 'She gets dressed after breakfast.', 'Cô ấy mặc quần áo sau bữa sáng.', 'BEGINNER', 'Daily Routine'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 1) AND position = 2), 'schedule', '/ˈskedʒuːl/', 'lịch trình', 'NOUN', 'My schedule is busy on Monday.', 'Lịch trình của tôi bận vào thứ Hai.', 'BEGINNER', 'Time and Schedule'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 1) AND position = 2), 'quarter', '/ˈkwɔːrtər/', 'một phần tư; mười lăm phút', 'NOUN', 'The class starts at a quarter past eight.', 'Lớp học bắt đầu lúc tám giờ mười lăm.', 'BEGINNER', 'Time and Schedule'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 1) AND position = 2), 'appointment', '/əˈpɔɪntmənt/', 'cuộc hẹn', 'NOUN', 'I have a dentist appointment at two.', 'Tôi có cuộc hẹn nha sĩ lúc hai giờ.', 'BEGINNER', 'Time and Schedule'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 2) AND position = 1), 'menu', '/ˈmenjuː/', 'thực đơn', 'NOUN', 'Could I see the menu, please?', 'Cho tôi xem thực đơn được không?', 'BEGINNER', 'Food and Drinks'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 2) AND position = 1), 'ingredient', '/ɪnˈɡriːdiənt/', 'nguyên liệu', 'NOUN', 'What ingredients are in this dish?', 'Món này có những nguyên liệu gì?', 'BEGINNER', 'Food and Drinks'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 2) AND position = 1), 'bill', '/bɪl/', 'hóa đơn', 'NOUN', 'Could we have the bill, please?', 'Cho chúng tôi xin hóa đơn được không?', 'BEGINNER', 'Food and Drinks'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 2) AND position = 2), 'price', '/praɪs/', 'giá', 'NOUN', 'The price includes tax.', 'Giá đã bao gồm thuế.', 'BEGINNER', 'Shopping'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 2) AND position = 2), 'size', '/saɪz/', 'kích cỡ', 'NOUN', 'Do you have this in a larger size?', 'Bạn có món này với kích cỡ lớn hơn không?', 'BEGINNER', 'Shopping'),
