INSERT INTO grammar_topics (course_id, lesson_id, title, description, formula, usage_text, example, note, level) VALUES
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 1) AND position = 1), 'Present Simple for Routines', 'Hiện tại đơn diễn tả thói quen và hoạt động lặp lại.', 'S + V(s/es) + O', 'Dùng với every day, usually, often và các lịch sinh hoạt.', 'He walks to school every day.', 'Thêm s/es khi chủ ngữ là he, she hoặc it.', 'BEGINNER'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 1) AND position = 2), 'Prepositions of Time', 'At, on và in được dùng với các loại mốc thời gian khác nhau.', 'at + time; on + day/date; in + month/year/part of day', 'At cho giờ, on cho ngày, in cho tháng, năm và buổi.', 'The meeting is at 9 a.m. on Friday.', 'Dùng at night nhưng in the morning.', 'BEGINNER'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 2) AND position = 1), 'Polite Requests with Would Like', 'Would like diễn tả mong muốn lịch sự.', 'S + would like + noun/to-infinitive', 'Dùng khi gọi món, mua hàng hoặc nói điều mình muốn.', 'I would like a glass of water.', 'Không dùng would like + V-ing.', 'BEGINNER'),
((SELECT id FROM courses WHERE slug = 'everyday-english-essentials'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND position = 2) AND position = 2), 'How Much and How Many', 'How much hỏi lượng không đếm được hoặc giá; how many hỏi số lượng đếm được.', 'How much + uncountable noun; How many + plural countable noun', 'Dùng khi hỏi giá, lượng và số lượng.', 'How many shirts do you need?', 'How much is also used without a noun to ask the price.', 'BEGINNER');
