((SELECT id FROM exercises WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND title = 'Everyday English Essentials – Final Check'), 'SINGLE_CHOICE', 'Từ hoặc cụm từ nào có nghĩa là “cuộc hẹn”?', '“appointment” có nghĩa là “cuộc hẹn”. Ví dụ: I have a dentist appointment at two.', 10.00, 'appointment', 6),
((SELECT id FROM exercises WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND title = 'Everyday English Essentials – Final Check'), 'SINGLE_CHOICE', 'Công thức hoặc mẫu cấu trúc phù hợp nhất với chủ điểm “Present Simple for Routines” là gì?', 'Hiện tại đơn diễn tả thói quen và hoạt động lặp lại. Mẫu dùng trong dữ liệu: S + V(s/es) + O.', 10.00, 'S + V(s/es) + O', 7),
