((SELECT id FROM exercises WHERE course_id = (SELECT id FROM courses WHERE slug = 'everyday-english-essentials') AND title = 'Everyday English Essentials – Final Check'), 'SINGLE_CHOICE', 'Công thức hoặc mẫu cấu trúc phù hợp nhất với chủ điểm “Polite Requests with Would Like” là gì?', 'Would like diễn tả mong muốn lịch sự.', 10.00, 'S + would like + noun/to-infinitive', 9),
