((SELECT id FROM courses WHERE slug = 'reading-everyday-texts'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'reading-everyday-texts') AND position = 2) AND position = 2), 'Sequence Connectors', 'Từ nối giúp tổ chức trình tự câu chuyện.', 'First, next, then, after that, finally', 'Dùng để kể sự kiện theo thứ tự.', 'First, Mia opened the box. Then, she found a note.', 'Không lặp then ở mọi câu; kết hợp nhiều từ nối.', 'ELEMENTARY');
