INSERT INTO grammar_topics (course_id, lesson_id, title, description, formula, usage_text, example, note, level) VALUES
((SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns') AND position = 1) AND position = 1), 'Word Form by Sentence Position', 'Vị trí trong câu giúp xác định từ loại cần dùng.', 'determiner + adjective + noun; verb + adverb', 'Dùng để chọn dạng từ đúng trong bài điền từ.', 'The team completed the task successfully.', 'Quan sát từ đứng trước và sau khoảng trống.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns') AND position = 1) AND position = 2), 'Common Affix Patterns', 'Tiền tố thay đổi nghĩa; hậu tố thường thay đổi từ loại.', 'prefix + root + suffix', 'Dùng để đoán nghĩa và từ loại.', 'un + predict + able = unpredictable', 'Không phải từ nào cũng kết hợp với mọi tiền tố hoặc hậu tố.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns') AND position = 2) AND position = 1), 'Collocation Patterns', 'Một số động từ và tính từ thường kết hợp cố định với danh từ.', 'verb + noun; adjective + noun', 'Dùng để diễn đạt tự nhiên hơn.', 'take a break; strong coffee; heavy rain', 'Không dịch từng từ trực tiếp từ tiếng Việt.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'vocabulary-through-word-patterns') AND position = 2) AND position = 2), 'Separable Phrasal Verbs', 'Một số phrasal verb cho phép tân ngữ đứng giữa động từ và tiểu từ.', 'verb + object + particle / verb + particle + object', 'Dùng với các phrasal verb như turn down và pick up.', 'Turn the music down.', 'Đại từ tân ngữ phải đứng giữa: turn it down.', 'INTERMEDIATE');
