((SELECT id FROM courses WHERE slug = 'grammar-for-real-communication'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'grammar-for-real-communication') AND position = 1) AND position = 2), 'recently', '/ˈriːsntli/', 'gần đây', 'ADVERB', 'I have recently started a new course.', 'Gần đây tôi đã bắt đầu một khóa học mới.', 'INTERMEDIATE', 'Past and Perfect'),
