((SELECT id FROM courses WHERE slug = 'grammar-for-real-communication'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'grammar-for-real-communication') AND position = 2) AND position = 1), 'arrangement', '/əˈreɪndʒmənt/', 'sự sắp xếp, lịch hẹn', 'NOUN', 'We have a dinner arrangement for Friday.', 'Chúng tôi có lịch ăn tối vào thứ Sáu.', 'INTERMEDIATE', 'Future Forms'),
