INSERT INTO grammar_topics (course_id, lesson_id, title, description, formula, usage_text, example, note, level) VALUES
((SELECT id FROM courses WHERE slug = 'grammar-for-real-communication'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'grammar-for-real-communication') AND position = 1) AND position = 1), 'Present Simple vs Present Continuous', 'Hiện tại đơn cho thói quen; hiện tại tiếp diễn cho hành động đang diễn ra hoặc tạm thời.', 'S + V(s/es); S + am/is/are + V-ing', 'Chọn thì dựa vào bản chất và thời gian của hành động.', 'He usually drives, but today he is taking the bus.', 'Các động từ trạng thái thường không dùng dạng tiếp diễn.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'grammar-for-real-communication'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'grammar-for-real-communication') AND position = 1) AND position = 2), 'Past Simple vs Present Perfect', 'Quá khứ đơn dùng với thời gian đã kết thúc; hiện tại hoàn thành liên hệ với hiện tại.', 'S + V2/ed; S + have/has + V3', 'Dùng past simple với yesterday/in 2024; present perfect với ever/never/yet.', 'I visited Hue last year. I have visited Hue twice.', 'Không dùng present perfect với mốc quá khứ đã kết thúc.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'grammar-for-real-communication'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'grammar-for-real-communication') AND position = 2) AND position = 1), 'Will, Going To and Present Continuous', 'Ba dạng tương lai thể hiện quyết định, dự định và lịch hẹn khác nhau.', 'will + V; be going to + V; be + V-ing + future time', 'Dùng theo mục đích và mức độ sắp xếp của kế hoạch.', 'I will answer. I am going to exercise. I am meeting Lan at six.', 'Không dùng một dạng tương lai cho mọi trường hợp.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'grammar-for-real-communication'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'grammar-for-real-communication') AND position = 2) AND position = 2), 'First Conditional and Should', 'Câu điều kiện loại 1 nói về khả năng thực tế; should đưa lời khuyên.', 'If + present simple, will + V; S + should + V', 'Dùng cho kế hoạch có điều kiện và lời khuyên.', 'If it rains, we will stay home. You should take an umbrella.', 'Không dùng will ngay sau if trong cấu trúc cơ bản.', 'INTERMEDIATE');
