INSERT INTO grammar_topics (course_id, lesson_id, title, description, formula, usage_text, example, note, level) VALUES
((SELECT id FROM courses WHERE slug = 'speaking-with-confidence'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'speaking-with-confidence') AND position = 1) AND position = 1), 'Open and Closed Questions', 'Câu hỏi mở tạo câu trả lời dài; câu hỏi đóng thường trả lời yes/no.', 'Wh-word + auxiliary + S + V? / Auxiliary + S + V?', 'Dùng câu hỏi mở để duy trì hội thoại.', 'What did you enjoy most about the trip?', 'Không đặt liên tiếp quá nhiều câu hỏi như phỏng vấn.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'speaking-with-confidence'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'speaking-with-confidence') AND position = 1) AND position = 2), 'Past Simple and Past Continuous', 'Past continuous tạo bối cảnh; past simple kể sự kiện chính.', 'S + was/were + V-ing; S + V2/ed', 'Dùng khi kể một hành động đang diễn ra bị một sự kiện xen vào.', 'I was walking home when it started to rain.', 'When thường giới thiệu sự kiện ngắn; while thường đi với hành động kéo dài.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'speaking-with-confidence'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'speaking-with-confidence') AND position = 2) AND position = 1), 'Opinion Clauses', 'Các cụm mở đầu giúp tổ chức quan điểm và mức độ chắc chắn.', 'I think/believe that... / In my view,... / From my experience,...', 'Dùng trước quan điểm, lý do và ví dụ.', 'In my view, flexible schedules improve productivity.', 'Tránh lặp I think ở mọi câu.', 'INTERMEDIATE'),
((SELECT id FROM courses WHERE slug = 'speaking-with-confidence'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'speaking-with-confidence') AND position = 2) AND position = 2), 'Presentation Signposting', 'Các cụm chuyển phần làm bài nói mạch lạc.', 'First, I will... / Let us move on to... / To sum up,...', 'Dùng ở phần mở đầu, chuyển ý và kết luận.', 'Let us move on to the second point.', 'Không dùng quá nhiều cụm chuyển ý trong một đoạn ngắn.', 'INTERMEDIATE');
