((SELECT id FROM courses WHERE slug = 'critical-english-for-digital-life'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'critical-english-for-digital-life') AND position = 1) AND position = 2), 'Reporting Verbs', 'Reporting verbs cho biết mức độ chắc chắn hoặc thái độ của nguồn.', 'source + says/claims/reports/suggests + that-clause', 'Dùng khi tóm tắt và đánh giá thông tin.', 'The study suggests that screen time affects sleep.', 'Claims không đồng nghĩa với proves.', 'ADVANCED'),
