((SELECT id FROM courses WHERE slug = 'critical-english-for-digital-life'), (SELECT id FROM lessons WHERE chapter_id = (SELECT id FROM chapters WHERE course_id = (SELECT id FROM courses WHERE slug = 'critical-english-for-digital-life') AND position = 2) AND position = 2), 'Hedging and Conditional Arguments', 'Hedging giúp tránh khẳng định quá tuyệt đối; conditionals trình bày quan hệ điều kiện.', 'may/might/could + V; If + clause, result clause', 'Dùng khi bằng chứng có giới hạn hoặc khi dự đoán tác động.', 'Excessive use may reduce sleep quality. If users set limits, they may focus better.', 'Hedging không làm lập luận yếu; nó thể hiện độ chính xác.', 'ADVANCED');
